const explorer = await __helpers.Explorer(code);
const randomIndex = explorer.allFunctions.getRandomIndex?.variables.randomIndex;
const validForms = [
    "const randomIndex = darkColorsArr.length * Math.random()",
    "const randomIndex = Math.random() * darkColorsArr.length",
    "const randomIndex = Math.floor(darkColorsArr.length * Math.random())",
    "const randomIndex = Math.floor(Math.random() * darkColorsArr.length)",
];
assert.isTrue(validForms.some(form => randomIndex?.matches(form)));

const explorer = await __helpers.Explorer(code);
const randomIndex = explorer.allFunctions.getRandomIndex?.variables.randomIndex;
const validForms = [
    "const randomIndex = Math.floor(darkColorsArr.length * Math.random())",
    "const randomIndex = Math.floor(Math.random() * darkColorsArr.length)",
];
assert.isTrue(validForms.some(form => randomIndex?.matches(form)));

const explorer = await __helpers.Explorer(code);
const body = explorer.variables.body;
assert.isTrue(body?.matches("const body = document.querySelector(\"body\")")); // treats "body" and 'body' the same;

const explorer = await __helpers.Explorer(code);
const bgHexCodeSpanElement = explorer.variables.bgHexCodeSpanElement;
assert.isTrue(bgHexCodeSpanElement?.matches("const bgHexCodeSpanElement = document.querySelector(\"#bg-hex-code\")"));

const explorer = await __helpers.Explorer(code);
const color = explorer.allFunctions.changeBackgroundColor?.variables.color;
assert.isTrue(color?.matches("const color = darkColorsArr[getRandomIndex()]"));

const explorer = await __helpers.Explorer(code);
const btn = explorer.variables.btn;
assert.isTrue(btn?.matches("const btn = document.querySelector(\"#btn\")"));
